using System.Runtime.InteropServices;
using System.Numerics;

namespace ProdOp;

public static class MathOps
{
    /// <summary>Computes the product of all elements using SIMD vectorization.</summary>
    public static float Product(ReadOnlySpan<float> values)
    {
        if (values.IsEmpty) return 0f;

        int i = 0;

        if (Vector.IsHardwareAccelerated && values.Length >= Vector<float>.Count)
        {
            var vProduct = Vector<float>.One;
            var vectors = MemoryMarshal.Cast<float, Vector<float>>(values);

            for (int v = 0; v < vectors.Length; v++)
                vProduct *= vectors[v];

            i = vectors.Length * Vector<float>.Count;

            // Reduce vector lanes to scalar
            float product = vProduct[0];
            for (int lane = 1; lane < Vector<float>.Count; lane++)
                product *= vProduct[lane];

            // Handle remaining elements
            for (; i < values.Length; i++)
                product *= values[i];

            return product;
        }

        // Scalar fallback with 4x unrolling to exploit ILP
        float p0 = 1f, p1 = 1f, p2 = 1f, p3 = 1f;
        int limit = values.Length - 3;
        for (; i < limit; i += 4)
        {
            p0 *= values[i];
            p1 *= values[i + 1];
            p2 *= values[i + 2];
            p3 *= values[i + 3];
        }
        float result = p0 * p1 * p2 * p3;
        for (; i < values.Length; i++)
            result *= values[i];

        return result;
    }
}

